/////////////////////////////////////////////////////////////////////////

class ParticleGroup {

  static populate(aGroup){
    for (let i = 0; i < aGroup.amount; i++){
      aGroup.container.push(new Particle(Math.round(Math.random()*width / (unit / TWO_PI)) * unit/TWO_PI, Math.round(Math.random()*height / (unit/TWO_PI)) *unit/TWO_PI, random(aGroup.sizeRange[0], aGroup.sizeRange[1])));
    }
  }

  constructor(color, amount, sizeRange = [0.1, 0.3]){
    this.color = color;
    this.sizeRange = sizeRange;
    this.amount = amount;
    this.container = [];
    this.populated=false;
  }

  update(){
    if (this.populated==false){
      ParticleGroup.populate(this);
      this.populated=true;
    }

    for (let particles of this.container){
      fill(this.color);
      particles.move();
      particles.checkEdge();
      particles.display();
    }
  }
  }

/////////////////////////////////////////////////////////////////////////

class Particle {
  constructor(x, y, size) {
    this.dir = createVector(0, 0);
    this.vel = createVector(size/2, size/2);
    this.pos = createVector(x, y);
    this.speed = random([size*unit/2, -size*unit/2]);
    this.size = size;
    this.angle = TWO_PI;
    this.noiseScale = noiseScale;
    this.well=false;
  }

  move() {
    this.angle = noise(this.pos.x /(this.noiseScale), this.pos.y /(this.noiseScale));
    this.angle *= (TWO_PI);

    this.vel.rotate((Math.tan((this.angle*this.size)*PI*11/4)));
		this.pos.add(this.vel);
  }

  checkEdge() {

    if (this.pos.x < 0 || this.pos.x > width || this.pos.y < 0 || this.pos.y > height) {
      this.pos.x = round(random(width) / (unit)) * unit;
      this.pos.y = round(random(height) / (unit)) * unit;
      this.speed*=random([1, -1]);
    }

  }

  display() {
    ellipse(this.pos.x, this.pos.y, this.size);
  }
}

